UPDATE capture_inputs
SET status='SUCCEEDED', error_message=NULL, completed_at=#{completedAt}, processing_token=NULL,
    lease_expires_at=NULL, updated_at=#{completedAt}
WHERE id=#{id} AND status='PROCESSING' AND processing_token=#{token}

UPDATE capture_inputs
SET status='FAILED', error_message=#{errorMessage}, completed_at=#{completedAt}, processing_token=NULL,
    lease_expires_at=NULL, updated_at=#{completedAt}
WHERE id=#{id} AND status='PROCESSING' AND processing_token=#{token}
